[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param(
  [ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')]
  [string]$Action='Check',
  [string]$StatePath="$PSScriptRoot\state.json",
  [string]$LogPath="$PSScriptRoot\events.jsonl"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$Experiment='EXP-066';$ServiceName='HPNetworkCap';$ServiceKey="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName"
function Write-Event([string]$Event,[string]$Result,$Data){$d=Split-Path -Parent $LogPath;if($d -and -not(Test-Path $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$sid=([Security.Principal.WindowsIdentity]::GetCurrent().User.Value);([ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$Experiment;action=$Action;event=$Event;result=$Result;computer=$env:COMPUTERNAME;userSid=$sid;data=$Data}|ConvertTo-Json -Compress -Depth 18)|Add-Content -LiteralPath $LogPath -Encoding UTF8}
function Test-Elevation {$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
function Same($A,$B){($A|ConvertTo-Json -Compress -Depth 18) -eq ($B|ConvertTo-Json -Compress -Depth 18)}
function Get-Exe([string]$p){if($p.TrimStart().StartsWith('"')){return ([regex]::Match($p,'^\s*"([^"]+)"')).Groups[1].Value};return ([regex]::Match($p,'^\s*([^\s]+\.exe)')).Groups[1].Value}
function Get-Reg([string]$n){$k=Get-Item $ServiceKey;if($k.GetValueNames() -notcontains $n){return [pscustomobject]@{Exists=$false;Kind=$null;Data=$null}};[pscustomobject]@{Exists=$true;Kind=$k.GetValueKind($n).ToString();Data=$k.GetValue($n,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)}}
function Set-Reg([string]$n,$s){$k=Get-Item $ServiceKey;if($s.Exists){$k.SetValue($n,$s.Data,[Enum]::Parse([Microsoft.Win32.RegistryValueKind],[string]$s.Kind,$true))}elseif($k.GetValueNames() -contains $n){Remove-ItemProperty $ServiceKey -Name $n}}
function Get-Management {$cs=Get-CimInstance Win32_ComputerSystem;$mdm=$false;$r='HKLM:\SOFTWARE\Microsoft\Enrollments';if(Test-Path $r){foreach($k in Get-ChildItem $r -ErrorAction SilentlyContinue){$p=Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue;if($p.ProviderID -or $p.UPN -or $p.DiscoveryServiceFullURL){$mdm=$true;break}}};$ccm=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue);[pscustomobject]@{DomainJoined=[bool]$cs.PartOfDomain;Mdm=$mdm;ConfigMgr=$ccm;Managed=([bool]$cs.PartOfDomain -or $mdm -or $ccm)}}
function Get-Protected {$n=@('WinDefend','mpssvc','wuauserv','UsoSvc','BITS','TermService','Tailscale','Dhcp','Dnscache','NlaSvc','RasMan');@($n|ForEach-Object{Get-CimInstance Win32_Service -Filter "Name='$_'" -ErrorAction SilentlyContinue}|Where-Object{$_}|Select-Object Name,StartMode,State,PathName|Sort-Object Name)}
function Get-Network {$a=@(Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue|Select-Object Name,InterfaceDescription,Status,MacAddress,LinkSpeed,DriverInformation|Sort-Object Name);$b=@(Get-NetAdapterBinding -AllBindings -ErrorAction SilentlyContinue|Select-Object Name,DisplayName,ComponentID,Enabled|Sort-Object Name,ComponentID);$ip=@(Get-NetIPConfiguration -All -ErrorAction SilentlyContinue|ForEach-Object{[pscustomobject]@{InterfaceAlias=$_.InterfaceAlias;InterfaceIndex=$_.InterfaceIndex;IPv4=@($_.IPv4Address.IPAddress);IPv6=@($_.IPv6Address.IPAddress);Gateway=@($_.IPv4DefaultGateway.NextHop);Dns=@($_.DNSServer.ServerAddresses)}}|Sort-Object InterfaceIndex);[pscustomobject]@{Adapters=$a;Bindings=$b;IP=$ip}}
function Get-HpApps {$paths=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*');@($paths|ForEach-Object{Get-ItemProperty $_ -ErrorAction SilentlyContinue}|Where-Object{$_.Publisher -match '(?i)HP|Hewlett-Packard' -or $_.DisplayName -match '(?i)OMEN|HP'}|Select-Object DisplayName,DisplayVersion,Publisher|Sort-Object DisplayName)}
function Get-Candidate {$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$m=Get-Management;$r=@();if($os.Caption -notmatch 'Windows 11'){$r+='Windows 11 required'};if($cs.Manufacturer -notmatch '(?i)^HP$|Hewlett-Packard'){$r+='HP platform required'};if(-not(Test-Elevation)){$r+='elevation required'};if($m.Managed){$r+='enterprise management ownership detected'};$svc=@(Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction SilentlyContinue);if($svc.Count -ne 1){$r+='exactly one HPNetworkCap service required';return [pscustomobject]@{Supported=$false;Reasons=$r;Service=$null;Management=$m;Protected=Get-Protected;Network=Get-Network;HpApps=Get-HpApps;EvidenceStatus='needs-evidence'}};$s=$svc[0];if($s.DisplayName -notmatch '(?i)HP.*Network.*HSA'){$r+='service display identity refused'};$exe=Get-Exe $s.PathName;if((Split-Path -Leaf $exe) -notmatch '(?i)^NetworkCap\.exe$'){$r+='NetworkCap.exe identity required'};if(-not(Test-Path $exe -PathType Leaf)){$r+='service executable missing'};$sig=$null;$hash=$null;$ver=$null;if(Test-Path $exe -PathType Leaf){$sig=Get-AuthenticodeSignature $exe;if($sig.Status -ne 'Valid' -or -not $sig.SignerCertificate -or $sig.SignerCertificate.Subject -notmatch '(?i)HP Inc|Hewlett-Packard'){$r+='HP publisher signature refused'};$hash=(Get-FileHash $exe -Algorithm SHA256).Hash;$ver=(Get-Item $exe).VersionInfo.FileVersion};$gs=Get-Service $ServiceName;$deps=@($gs.ServicesDependedOn|ForEach-Object Name|Sort-Object);$dents=@($gs.DependentServices|ForEach-Object Name|Sort-Object);foreach($x in @($deps+$dents)){if($x -match '(?i)WinDefend|mpssvc|bfe|wuauserv|bits|Tailscale|Omnissa|TermService|RasMan|NlaSvc|Dhcp|Dnscache'){$r+="Protected dependency refused: $x"}};if($s.ServiceType -match '(?i)kernel|file system|driver'){$r+='driver-backed service refused'};if($s.StartMode -eq 'Disabled'){$r+='Disabled baseline refused'};$apps=Get-HpApps;if(@($apps|Where-Object{$_.DisplayName -match '(?i)OMEN Gaming Hub|OMEN Command Center'}).Count -gt 0){$r+='OMEN-dependent state requires physical demand-start evidence before mutation'};$svcState=[pscustomobject]@{Name=$s.Name;DisplayName=$s.DisplayName;PathName=$s.PathName;StartMode=$s.StartMode;State=$s.State;StartName=$s.StartName;ServiceType=$s.ServiceType;Executable=$exe;ExecutableVersion=$ver;ExecutableHash=$hash;SignatureThumbprint=if($sig -and $sig.SignerCertificate){$sig.SignerCertificate.Thumbprint}else{$null};DelayedAutoStart=Get-Reg 'DelayedAutoStart';Dependencies=$deps;Dependents=$dents};[pscustomobject]@{Supported=($r.Count -eq 0);Reasons=$r;OS=$os.Caption;Build=$os.BuildNumber;Manufacturer=$cs.Manufacturer;Model=$cs.Model;Management=$m;Service=$svcState;Protected=Get-Protected;Network=Get-Network;HpApps=$apps;EvidenceStatus='needs-evidence'}}
function Save-State($s){if(Test-Path $StatePath){throw 'State overwrite refused'};$d=Split-Path -Parent $StatePath;if($d -and -not(Test-Path $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$x=[ordered]@{schemaVersion=1;experiment=$Experiment;computer=$env:COMPUTERNAME;userSid=([Security.Principal.WindowsIdentity]::GetCurrent().User.Value);capturedBootUtc=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');support=$s;network=$s.Network;protected=$s.Protected;evidenceStatus='needs-evidence'};$x|ConvertTo-Json -Depth 18|Set-Content $StatePath -Encoding UTF8;$x}
function Read-State {$s=Get-Content $StatePath -Raw|ConvertFrom-Json;if($s.experiment -ne $Experiment -or $s.computer -ne $env:COMPUTERNAME -or $s.userSid -ne ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value)){throw 'State identity refused'};$s}
function Assert-Safe($st,$c){if(-not $c.Supported){throw('Support drift detected: '+($c.Reasons -join '; '))};$o=$st.support.Service;if($c.Service.Name -ne $o.Name -or $c.Service.PathName -ne $o.PathName -or $c.Service.ExecutableHash -ne $o.ExecutableHash -or $c.Service.SignatureThumbprint -ne $o.SignatureThumbprint){throw 'Service identity drift detected'};if(-not(Same $c.Service.Dependencies $o.Dependencies) -or -not(Same $c.Service.Dependents $o.Dependents)){throw 'Service dependency drift detected'};if(-not(Same $c.Management $st.support.Management)){throw 'Management state drift detected'};if(-not(Same (Get-Protected) $st.protected)){throw 'Protected security, update, or remote-access state drift detected'};if(-not(Same (Get-Network) $st.network)){throw 'Protected network stack drift detected'}}
function Set-Mode([string]$m){Set-Service -Name $ServiceName -StartupType $(if($m -eq 'Manual'){'Manual'}else{'Automatic'})}
try{$c=Get-Candidate;Write-Event 'support-detection' $(if($c.Supported){'pass'}else{'refused'}) $c;switch($Action){'Check'{$c};'Capture'{if(-not $c.Supported){throw($c.Reasons -join '; ')};Save-State $c};'DryRun'{if(-not $c.Supported){throw($c.Reasons -join '; ')};$x=[pscustomobject]@{WouldChange=($c.Service.StartMode -ne 'Manual');MutationCount=if($c.Service.StartMode -eq 'Manual'){0}else{1};Service=$ServiceName;From=$c.Service.StartMode;To='Manual';PreserveRunningState=$true;NetworkStackPreserved=$true;EvidenceStatus='needs-evidence'};Write-Event 'dry-run' 'pass' $x;$x};'Apply'{$st=Read-State;Assert-Safe $st $c;$o=$st.support.Service;if($c.Service.StartMode -eq 'Manual'){Write-Event 'apply' 'idempotent' @{mutationCount=0};return $c.Service};if($c.Service.StartMode -ne $o.StartMode -or -not(Same $c.Service.DelayedAutoStart $o.DelayedAutoStart)){throw 'Configuration drift detected before Apply'};$running=$c.Service.State;if($WhatIfPreference){Write-Event 'apply' 'whatif' @{mutationCount=0};return};if($PSCmdlet.ShouldProcess($ServiceName,'Set startup mode to Manual')){Set-Mode 'Manual'};$a=Get-Candidate;if($a.Service.StartMode -ne 'Manual' -or $a.Service.State -ne $running -or -not(Same $a.Service.DelayedAutoStart $o.DelayedAutoStart)){throw 'Apply verification failed'};if(-not(Same (Get-Network) $st.network)){throw 'Network stack changed during Apply'};Write-Event 'apply' 'pass' @{before=$c.Service;after=$a.Service};$a.Service};'Verify'{$st=Read-State;Assert-Safe $st $c;if($c.Service.StartMode -ne 'Manual'){throw 'Manual treatment absent'};Write-Event 'verify' 'pass' $c.Service;$c.Service};'VerifyReboot'{$st=Read-State;Assert-Safe $st $c;$boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime();if($boot -le [datetime]$st.capturedBootUtc){throw 'Later boot required for reboot persistence verification'};if($c.Service.StartMode -ne 'Manual'){throw 'Reboot persistence failed'};Write-Event 'verify-reboot' 'pass' @{bootUtc=$boot.ToString('o');service=$c.Service};$c.Service};'Rollback'{$st=Read-State;Assert-Safe $st $c;$o=$st.support.Service;if($c.Service.StartMode -eq $o.StartMode -and $c.Service.State -eq $o.State -and (Same $c.Service.DelayedAutoStart $o.DelayedAutoStart)){Write-Event 'rollback' 'idempotent' @{mutationCount=0};return $c.Service};if($c.Service.StartMode -ne 'Manual'){throw 'Rollback collision detected'};if($WhatIfPreference){Write-Event 'rollback' 'whatif' @{restore=$o};return};if($PSCmdlet.ShouldProcess($ServiceName,'Restore exact captured service state')){Set-Mode $o.StartMode;Set-Reg 'DelayedAutoStart' $o.DelayedAutoStart;if($o.State -eq 'Running' -and (Get-Service $ServiceName).Status -ne 'Running'){Start-Service $ServiceName};if($o.State -eq 'Stopped' -and (Get-Service $ServiceName).Status -ne 'Stopped'){Stop-Service $ServiceName}};$a=Get-Candidate;if($a.Service.StartMode -ne $o.StartMode -or $a.Service.State -ne $o.State -or -not(Same $a.Service.DelayedAutoStart $o.DelayedAutoStart) -or -not(Same (Get-Network) $st.network)){throw 'Exact rollback verification failed'};Write-Event 'rollback' 'pass' $a.Service;$a.Service}}}catch{Write-Event 'failure' 'failed' @{message=$_.Exception.Message};throw}
